if (k == 0 || points.empty()) {
        return {};
    }

    std::vector<std::pair<double, size_t>> distances;
    distances.reserve(points.size());

    for (size_t i = 0; i < points.size(); ++i) {
        double dx = points[i].x - searchPoint.x;
        double dy = points[i].y - searchPoint.y;
        double dz = points[i].z - searchPoint.z;
        double distSq = dx * dx + dy * dy + dz * dz;
        distances.push_back({distSq, i});
    }

    std::size_t resultSize = std::min(k, points.size());
    std::partial_sort(distances.begin(), distances.begin() + resultSize, distances.end());

    std::vector<size_t> neighbors;
    neighbors.reserve(resultSize);
    for (size_t i = 0; i < resultSize; ++i) {
        neighbors.push_back(distances[i].second);
    }

    return neighbors;

